#!/bin/sh
# Tests the guarded PRODUCTION step-0 files (supabase/production/*_0_tracking.sql, generated by
# scripts/production/gen_bootstrap.py) on a throwaway LOCAL database built from main's 25 migrations, i.e. the
# schema production has (production_fingerprint_test.sh). The files only run on production's cluster id: the test
# runs copies in which that one constant is replaced by this server's, and checks nothing else differs.
# Never connects to a hosted database. Every check prints PASS: or FAIL:.
set -u
T="$(cd "$(dirname "$0")" && pwd)"; REPO="$(cd "$T/../.." && pwd)"
PROD_ID=7692130048193495360; LAST=20261027020000
P="psql -h ${PGSOCK:-/var/tmp/pgc} -p ${PGPORT:-54329} -U postgres -q"
W=$(mktemp -d); trap 'rm -rf "$W"' EXIT
BASE=ct_p0_base; DB=ct_p0
pass=0; fail=0
ok() { echo "PASS: $1"; pass=$((pass + 1)); }
ko() { echo "FAIL: $1"; fail=$((fail + 1)); }
q() { $P -d "$DB" -Atc "$1"; }
fresh() { $P -c "drop database if exists $DB" -c "create database $DB template $BASE" >/dev/null; }
run() { $P -d "$DB" -v ON_ERROR_STOP=1 -f "$1" > "$W/out" 2>&1; }
state() { q "select coalesce((select string_agg(version, ',' order by version) from supabase_migrations.schema_migrations), 'none')" 2>/dev/null || echo "no-tracking"; }
whole() { echo "$(state)#$(q "select coalesce(string_agg(key || '=' || value, ',' order by key), '') from public.app_secrets")#$($P -d "$DB" -At -f "$REPO/scripts/production/fingerprint.sql" | grep '|' | tr '\n' ';')"; }

# a production-like base: main's 25 migrations (no seed, no tracking), plus app_secrets rows like production's keys
$P -c "drop database if exists $BASE" -c "create database $BASE" >/dev/null 2>&1
D="env PGOPTIONS=-cclient_min_messages=warning $P -d $BASE -v ON_ERROR_STOP=1"
$D -f "$T/supabase_stub.sql" >/dev/null
for f in "$REPO"/supabase/migrations/*.sql; do v=$(basename "$f" | cut -d_ -f1); [ "$v" -le "$LAST" ] && $D -f "$f" >/dev/null; done
$D -f "$T/grants.sql" >/dev/null
$D -c "insert into public.app_secrets values ('dispatch_url', 'synthetic'), ('vapid_public', 'synthetic') on conflict do nothing" >/dev/null
LOCAL_ID=$($P -At -c "select system_identifier from pg_control_system()")
A="$REPO/supabase/production/apply_0_tracking.sql"; R="$REPO/supabase/production/rollback_0_tracking.sql"
sed "s/$PROD_ID/$LOCAL_ID/" "$A" > "$W/apply.sql"; sed "s/$PROD_ID/$LOCAL_ID/" "$R" > "$W/rollback.sql"
[ "$(diff "$A" "$W/apply.sql" | grep '^<' | grep -vc "$PROD_ID")" = 0 ] && [ "$(diff "$R" "$W/rollback.sql" | grep '^<' | grep -vc "$PROD_ID")" = 0 ] && [ "$(grep -c "$PROD_ID" "$A")" = 2 ] \
  && ok "the test copies differ from the files only in the cluster id" || ko "copies differ in more than the cluster id"
python3 "$REPO/scripts/production/gen_bootstrap.py" > /dev/null && git -C "$REPO" diff --quiet -- supabase/production \
  && ok "the committed files are exactly the generator's output" || ko "supabase/production differs from the generator output"

refused() { # $1 label, $2 file, $3 expected text
  b0=$(whole)
  if run "$2"; then ko "$1: it ran"
  elif grep -q "$3" "$W/out" && [ "$(whole)" = "$b0" ]; then ok "$1 (refused, nothing changed)"
  else ko "$1: $(grep -m1 ERROR "$W/out")"; fi
}

fresh
refused "the real file on a database that is not production" "$A" "not the Classi production database"
refused "rollback before the apply" "$W/rollback.sql" "tracking table does not hold"
before=$(whole)
run "$W/apply.sql" && ok "step 0 applies on a production-like database" || { ko "apply failed"; cat "$W/out"; }
[ "$(q "select count(*) || ' ' || max(version) from supabase_migrations.schema_migrations")" = "25 $LAST" ] && ok "25 migrations recorded, newest $LAST" || ko "tracking content"
[ "$(q "select value from public.app_secrets where key = 'deploy_env'")" = production ] && ok "marker deploy_env = production" || ko "marker"
[ "$(q "select has_schema_privilege('anon', 'supabase_migrations', 'usage') or has_schema_privilege('authenticated', 'supabase_migrations', 'usage')")" = f ] \
  && ok "visitors and accounts cannot reach the tracking schema" || ko "tracking schema reachable by anon/authenticated"
after_fp=$($P -d "$DB" -At -f "$REPO/scripts/production/fingerprint.sql" | grep '|')
[ "$after_fp" = "$(cat "$REPO/scripts/production/expected_$LAST.txt")" ] && ok "the public schema is unchanged (same fingerprint)" || ko "public schema changed"
[ "$(q "select string_agg(key, ',' order by key) from public.app_secrets")" = "deploy_env,dispatch_url,vapid_public" ] && ok "no other secret row touched" || ko "app_secrets rows"
refused "step 0 twice" "$W/apply.sql" "already exists"
run "$W/rollback.sql" && ok "rollback applies" || { ko "rollback failed"; cat "$W/out"; }
after=$(whole); [ "$after" = "$before" ] && ok "after the rollback: exactly the state before step 0" || { ko "rollback left a difference"; echo "  before: $before"; echo "  after:  $after"; }

fresh; $P -d "$DB" -c "insert into public.app_secrets values ('deploy_env', 'staging')" >/dev/null
refused "a database with an environment marker (staging)" "$W/apply.sql" "marker is already set"
fresh; $P -d "$DB" -c "create schema supabase_migrations" >/dev/null
refused "a database that already has tracking" "$W/apply.sql" "already exists"
fresh; $P -d "$DB" -c "create or replace function public.clean_phone(p text) returns text language sql immutable set search_path = public as \$\$ select p \$\$" >/dev/null
refused "a changed function" "$W/apply.sql" "not the one recorded"
fresh; $P -d "$DB" -c "alter table public.reviews add column extra int" >/dev/null
refused "an extra column" "$W/apply.sql" "not the one recorded"
fresh; $P -d "$DB" -c "alter table public.reviews disable row level security" >/dev/null
refused "RLS off on a table" "$W/apply.sql" "not the one recorded"
fresh; $P -d "$DB" -c "grant execute on function public.is_admin() to anon" >/dev/null 2>&1; $P -d "$DB" -c "revoke execute on function public.admin_stats() from authenticated" >/dev/null
refused "changed function grants" "$W/apply.sql" "not the one recorded"
fresh; run "$W/apply.sql" >/dev/null; $P -d "$DB" -c "insert into supabase_migrations.schema_migrations (version, name) values ('20261031000000', 'production_hardening')" >/dev/null
refused "rollback after a newer migration was recorded" "$W/rollback.sql" "tracking table does not hold"

$P -c "drop database if exists $DB" -c "drop database if exists $BASE" >/dev/null 2>&1
echo "production step 0: $pass passed, $fail failed"
[ "$fail" = 0 ]
